363	    private BigDecimal applySurcharges(String procedureCode, BigDecimal amount, PricingContext context) {
364	        BigDecimal surcharged = amount;
365	
366	        if (context.getServiceDateTime() != null) {
367	            ZonedDateTime serviceTime = context.getServiceDateTime();
368	            int hour = serviceTime.getHour();
369	            DayOfWeek dayOfWeek = serviceTime.getDayOfWeek();
370	
371	            if (hour < 7 || hour > 18) {
372	                BigDecimal afterHours = SURCHARGE_RULES.get("AFTER_HOURS");
373	                if (afterHours != null) {
374	                    surcharged = surcharged.multiply(afterHours);
375	                }
376	            }
377	
378	            if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
379	                BigDecimal weekend = SURCHARGE_RULES.get("WEEKEND");
380	                if (weekend != null) {
381	                    surcharged = surcharged.multiply(weekend);
382	                }
383	            }
384	
385	            if (isHoliday(serviceTime.toLocalDate())) {
386	                BigDecimal holiday = SURCHARGE_RULES.get("HOLIDAY");
387	                if (holiday != null) {
388	                    surcharged = surcharged.multiply(holiday);
389	                }
390	            }
391	        }
392	
393	        if (Boolean.TRUE.equals(context.isUrgent())) {
394	            BigDecimal urgent = SURCHARGE_RULES.get("URGENT");
395	            if (urgent != null) {
396	                surcharged = surcharged.multiply(urgent);
397	            }
398	        }
399	
400	        if (Boolean.TRUE.equals(context.isStatOrder())) {
401	            String family = PROCEDURE_FAMILIES.get(procedureCode);
402	            if ("LABORATORY".equals(family)) {
403	                BigDecimal statLab = SURCHARGE_RULES.get("STAT_LAB");
404	                if (statLab != null) {
405	                    surcharged = surcharged.multiply(statLab);
406	                }
407	            }
408	        }
409	
410	        return surcharged;
411	    }
