433	                            break;
434	                        case "TX":
435	                            taxRate = new BigDecimal("0.0625");
436	                            break;
437	                        case "NY":
438	                            taxRate = new BigDecimal("0.08");
439	                            break;
440	                        case "FL":
441	                            taxRate = new BigDecimal("0.06");
442	                            break;
443	                        default:
444	                            taxRate = new BigDecimal("0.05");
445	                    }
446	                } else {
447	                    taxRate = new BigDecimal("0.05");
448	                }
449	                break;
450	            case "PROCEDURE":
451	                taxRate = new BigDecimal("0.03");
452	                break;
453	            default:
454	                taxRate = new BigDecimal("0.05");
455	        }
456	
457	        if (Boolean.TRUE.equals(context.isTaxExempt())) {
458	            taxRate = BigDecimal.ZERO;
459	        }
460	
461	        BigDecimal taxAmount = amount.multiply(taxRate);
462	        return amount.add(taxAmount);
463	    }
